function validate([s]) {
  if (typeof s !== 'string' || s.length < 4 || s.length > 100000) return 's needs 4 to 100000 letters.';
  if (s.length % 4 !== 0) return 'The length of s must be a multiple of 4.';
  if (!/^[QWER]+$/.test(s)) return "s may only contain 'Q', 'W', 'E' and 'R'.";
  return null;
}

