function balancedString(s) {
  const n = s.length;
  const quota = n / 4;
  const outside = new Map([['Q', 0], ['W', 0], ['E', 0], ['R', 0]]);
  for (const ch of s) {
    outside.set(ch, outside.get(ch) + 1);
  }
  const fits = () => [...outside.values()].every(count => count <= quota);
  if (fits()) {
    return 0;
  }
  let best = n;
  let left = 0;
  for (let right = 0; right < n; right++) {
    outside.set(s[right], outside.get(s[right]) - 1);
    while (left <= right && fits()) {
      best = Math.min(best, right - left + 1);
      outside.set(s[left], outside.get(s[left]) + 1);
      left++;
    }
  }
  return best;
}

brute:
function balancedString(s) {
  const n = s.length;
  const letters = ['Q', 'W', 'E', 'R'];
  const balanced = str => letters.every(c => str.split(c).length - 1 === n / 4);
  if (balanced(s)) return 0;
  // Try every window from shortest to longest; it works when no letter outside it exceeds n / 4.
  for (let len = 1; len <= n; len++) {
    for (let start = 0; start + len <= n; start++) {
      const rest = s.slice(0, start) + s.slice(start + len);
      if (letters.every(c => rest.split(c).length - 1 <= n / 4)) return len;
    }
  }
  return n;
}

