function generate(rand, size) {
  const letters = ['Q', 'W', 'E', 'R'];
  const n = size === 'large' ? 10000 : 4 * (1 + Math.floor(rand() * 5));
  // Random letter weights make some inputs nearly balanced and others heavily skewed.
  const weights = letters.map(() => rand() < 0.2 ? 0.05 : rand());
  const total = weights.reduce((a, b) => a + b, 0);
  let s = '';
  for (let i = 0; i < n; i++) {
    let pick = rand() * total, k = 0;
    while (k < 3 && pick >= weights[k]) { pick -= weights[k]; k++; }
    s += letters[k];
  }
  return [s];
}
